def forward(self, taskInfo):
    """Solve an ARC task by:
    1️⃣ Exhaustively searching a small DSL of primitive operations (crop, colour
       removal/replacement, bounding‑box, flip, transpose) over **all** colour
       values (0‑9) and all possible separator positions. The first primitive that
       matches **all** training examples is applied to the test input.
    2️⃣ If no deterministic primitive succeeds, query several answer agents with
       a high temperature (self‑consistency) and return the majority‑voted grid.
    3️⃣ As a final safety net, fall back to a single low‑temperature answer
       agent.
    Returns the output grid as a list of list of ints.
    """

    # ---------------------------------------------------------------------
    # Helper utilities
    # ---------------------------------------------------------------------
    def is_grid(g):
        """Return True if *g* is a list of lists (grid)."""
        return isinstance(g, list) and all(isinstance(r, list) for r in g)

    # Primitive operations --------------------------------------------------
    def crop_left(grid, col_idx):
        return [row[:col_idx] for row in grid]

    def crop_right(grid, col_idx):
        return [row[col_idx + 1 :] for row in grid]

    def crop_top(grid, row_idx):
        return grid[:row_idx]

    def crop_bottom(grid, row_idx):
        return grid[row_idx + 1 :]

    def remove_colour(grid, colour):
        return [[0 if cell == colour else cell for cell in row] for row in grid]

    def replace_colour(grid, src, dst):
        return [[dst if cell == src else cell for cell in row] for row in grid]

    def bbox_of_colour(grid, colour):
        rows = [i for i, row in enumerate(grid) if colour in row]
        cols = [j for j in range(len(grid[0])) if any(grid[i][j] == colour for i in range(len(grid)))]
        if not rows or not cols:
            return None
        r0, r1 = min(rows), max(rows) + 1
        c0, c1 = min(cols), max(cols) + 1
        return [grid[i][c0:c1] for i in range(r0, r1)]

    def flip_h(grid):
        return grid[::-1]

    def flip_v(grid):
        return [row[::-1] for row in grid]

    def transpose(grid):
        return [list(row) for row in zip(*grid)]

    # ---------------------------------------------------------------------
    # Guard – if there are no examples, directly ask a low‑temp model
    # ---------------------------------------------------------------------
    if not self.examples:
        fallback_instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        direct_agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        return direct_agent([taskInfo], fallback_instr)[0].content

    # ---------------------------------------------------------------------
    # Pre‑compute dimensions and colour set
    # ---------------------------------------------------------------------
    max_rows = max(len(ex["input"]) for ex in self.examples)
    max_cols = max(len(ex["input"][0]) for ex in self.examples)
    all_colours = set(range(10))  # ARC uses colours 0‑9

    # Helper to test a candidate primitive on all examples
    def candidate_matches(fn):
        for ex in self.examples:
            inp, out_expected = ex["input"], ex["output"]
            out_candidate = fn(inp)
            if out_candidate is None or out_candidate != out_expected:
                return False
        return True

    # ---------------------------------------------------------------------
    # 1️⃣ Exhaustive primitive search
    # ---------------------------------------------------------------------
    # 1.1 Crop primitives – search every column/row for a uniform colour
    for colour in all_colours:
        # vertical columns
        for col_idx in range(max_cols):
            # Verify column is uniform of this colour across **all** examples
            uniform = True
            for ex in self.examples:
                grid = ex["input"]
                if any(grid[r][col_idx] != colour for r in range(len(grid))):
                    uniform = False
                    break
            if not uniform:
                continue
            # Define helper functions to avoid lambda capture issues
            def fn_left(g, c=col_idx):
                return crop_left(g, c)

            def fn_right(g, c=col_idx):
                return crop_right(g, c)

            if candidate_matches(fn_left):
                return crop_left(self.test_input, col_idx)
            if candidate_matches(fn_right):
                return crop_right(self.test_input, col_idx)
        # horizontal rows
        for row_idx in range(max_rows):
            uniform = True
            for ex in self.examples:
                grid = ex["input"]
                if any(grid[row_idx][c] != colour for c in range(len(grid[0]))):
                    uniform = False
                    break
            if not uniform:
                continue
            def fn_top(g, r=row_idx):
                return crop_top(g, r)

            def fn_bottom(g, r=row_idx):
                return crop_bottom(g, r)

            if candidate_matches(fn_top):
                return crop_top(self.test_input, row_idx)
            if candidate_matches(fn_bottom):
                return crop_bottom(self.test_input, row_idx)

    # 1.2 Colour removal (replace with 0)
    for colour in all_colours:
        def fn_rem(g, col=colour):
            return remove_colour(g, col)
        if candidate_matches(fn_rem):
            return remove_colour(self.test_input, colour)

    # 1.3 Colour replacement (src → dst)
    for src in all_colours:
        for dst in all_colours:
            if src == dst:
                continue
            def fn_rep(g, s=src, d=dst):
                return replace_colour(g, s, d)
            if candidate_matches(fn_rep):
                return replace_colour(self.test_input, src, dst)

    # 1.4 Bounding‑box of a specific colour
    for colour in all_colours:
        def fn_bbox(g, col=colour):
            return bbox_of_colour(g, col)
        if candidate_matches(fn_bbox):
            return bbox_of_colour(self.test_input, colour)

    # 1.5 Flips and transpose (no parameters)
    if candidate_matches(flip_h):
        return flip_h(self.test_input)
    if candidate_matches(flip_v):
        return flip_v(self.test_input)
    if candidate_matches(transpose):
        return transpose(self.test_input)

    # ---------------------------------------------------------------------
    # 2️⃣ Self‑consistency direct‑answer stage (majority vote)
    # ---------------------------------------------------------------------
    def self_consistency_answer(num_samples=7):
        instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        collected = []
        for i in range(num_samples):
            agent = LLMAgentBase(
                output_fields=["answer"],
                agent_name=f"SC_Answer_{i}",
                role="ARC Solver",
                temperature=0.9,
            )
            ans = agent([taskInfo], instr)[0].content
            if is_grid(ans):
                collected.append(ans)
        if not collected:
            return None
        # Majority vote on hashable representation; tie‑break by first occurrence
        votes = {}
        for grid in collected:
            key = tuple(tuple(row) for row in grid)
            votes[key] = votes.get(key, 0) + 1
        best_key = max(votes.items(), key=lambda kv: kv[1])[0]
        return [list(row) for row in best_key]

    sc_grid = self_consistency_answer()
    if sc_grid is not None:
        return sc_grid

    # ---------------------------------------------------------------------
    # 3️⃣ Final fallback – low‑temperature direct answer
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    final_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFinal",
        role="ARC Solver",
        temperature=0.1,
    )
    final_grid = final_agent([taskInfo], final_instr)[0].content
    # Return whatever the model produced (grid or otherwise) – callers expect a grid.
    return final_grid if is_grid(final_grid) else final_grid
}
